package org.marketreview.nativeapp;
import org.json.*;
import java.net.URI;
import java.nio.charset.StandardCharsets;
final class SectorResearchModel {
 static void require(boolean b,String why){if(!b)throw new IllegalArgumentException(why);}
 static String json(Object o)throws Exception{return EvidenceReviewModel.json(o);}
 static String fingerprint(Object o)throws Exception{return EvidenceReviewModel.fingerprint(o);}
 static JSONObject object(JSONObject o,String k){JSONObject v=o.optJSONObject(k);return v==null?new JSONObject():v;}
 static JSONArray array(JSONObject o,String k){JSONArray v=o.optJSONArray(k);return v==null?new JSONArray():v;}
 static JSONObject scope(JSONObject s)throws Exception{require((s.optString("kind").equals("sector")||s.optString("kind").equals("industry"))&&!s.optString("id").trim().isEmpty()&&!s.optString("name").trim().isEmpty(),"需完整稳定主题身份和名称");require(json(s).getBytes(StandardCharsets.UTF_8).length<=25*1024*1024,"主题快照过大");return s;}
 static JSONObject seal(JSONObject r)throws Exception{return r.put("id",r.getString("kind")+":"+fingerprint(r));}
 static JSONObject packet(JSONObject s,JSONArray docs,String manual,String question)throws Exception{scope(s);for(int i=0;i<docs.length();i++){JSONObject ref=docs.getJSONObject(i),snap=object(ref,"snapshot");require((ref.optString("kind").equals("docs")||ref.optString("kind").equals("collections"))&&!ref.optString("id").isEmpty()&&ref.optString("id").equals(snap.optString("id"))&&ref.optString("bodyHash").equals(SourceAnalysisPacket.hash(snap.optString("text")+'\0'+snap.optString("originalText"))),"冻结来源身份/正文指纹无效");}require(!manual.trim().isEmpty()||docs.length()>0,"请选择或填写材料");String prompt="人工板块/产业研究交接。未执行在线AI。区分当日热度与月度持续性；月度缺失为未知，成员样本估计不可当指数事实。新闻为线索，需核验日期、原文、风险与反证；不推断成员、供应链归属或收入。\n主题完整快照：\n"+json(s)+"\n材料：\n"+manual+"\n本机来源：\n"+json(docs)+"\n问题：\n"+question;return seal(new JSONObject().put("kind","packets").put("scope",s).put("documents",docs).put("manual",manual).put("question",question).put("prompt",prompt).put("verification","manual-unverified"));}
 static JSONObject result(JSONObject p,String input)throws Exception{validate(p);require(p.optString("kind").equals("packets")&&!input.trim().isEmpty(),"需冻结材料包和完整回填");String text=input.trim(),proof="manual-no-returned-packet-proof";JSONArray candidates=new JSONArray();JSONObject o=null;try{new EvidenceReviewModel.Syntax(input).check();o=new JSONObject(input);}catch(Exception ignored){}
 if(o!=null&&o.optString("schema").equals("sector-research-return-v1")){require(o.optString("packetId").equals(p.optString("id"))&&o.optString("scopeId").equals(object(p,"scope").optString("id")),"返回材料包/主题身份不匹配");text=o.optString("report");require(!o.has("candidates")||o.optJSONArray("candidates")!=null,"候选需数组");candidates=array(o,"candidates");proof="returned-packet-id-matched-manual";}else{String start="WEBSTOCK_HOT_MARKET_ANALYSIS_START",end="WEBSTOCK_HOT_MARKET_ANALYSIS_END";int a=text.indexOf(start),b=text.indexOf(end);if(a>=0){require(b>a&&text.substring(b+end.length()).trim().isEmpty()&&text.substring(0,a).trim().isEmpty(),"手工回填标记不完整或含额外内容");text=text.substring(a+start.length(),b).trim();}}
 require(!text.isEmpty(),"回填报告为空");return seal(new JSONObject().put("kind","results").put("packetId",p.get("id")).put("packetSnapshot",p).put("scope",p.get("scope")).put("raw",input).put("text",text).put("candidates",candidates).put("binding",proof).put("verification","manual-unverified"));}
 static void list(JSONObject o,String key,boolean needed)throws Exception{require(!o.has(key)||o.optJSONArray(key)!=null,key+"需数组");JSONArray a=array(o,key);require(a.length()<=30&&(!needed||a.length()>0),key+"缺失或超过30项");for(int i=0;i<a.length();i++){require(a.get(i) instanceof String&&!a.getString(i).trim().isEmpty(),key+"项无效");String text=a.getString(i);if(key.equals("evidenceRefs")){URI u=new URI(text);require(("http".equals(u.getScheme())||"https".equals(u.getScheme()))&&u.getHost()!=null&&u.getUserInfo()==null,"来源链接需公开HTTP地址");require(!java.util.regex.Pattern.compile("(?:[?&])(token|password|api_key|access_token|secret)=",java.util.regex.Pattern.CASE_INSENSITIVE).matcher(text).find(),"来源链接含凭据参数");}if(key.equals("relatedCodes"))require(text.matches("[0-9]{6}"),"代码无效；不猜测市场");}}
 static JSONObject artifact(JSONObject o)throws Exception{String schema=o.optString("schema");boolean hot=schema.equals("webstock.market-hotspots/v1");require(hot||schema.equals("webstock.industry-chain-updates/v1"),"不支持的外部材料schema");JSONObject payload=object(o,"payload");String key=hot?"items":"chains";require(payload.optJSONArray(key)!=null,"材料行需数组");JSONArray rows=payload.getJSONArray(key);require(rows.length()>0&&rows.length()<=20,"材料需1至20行，未截断");for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);require(!r.optString("name").trim().isEmpty()&&!r.optString("thesis").trim().isEmpty(),"名称/逻辑缺失");list(r,"risks",true);list(r,"evidenceRefs",true);list(r,"relatedCodes",false);list(r,"drivers",false);if(!hot){list(r,"stages",true);list(r,"catalysts",false);}}return seal(new JSONObject().put("kind","artifacts").put("original",o).put("rows",rows).put("verification","external-unverified").put("association","unbound"));}
  static JSONArray batch(JSONObject o)throws Exception{java.util.Set<String> keys=new java.util.HashSet<>(java.util.Arrays.asList("schema","source","revision","asOf","automaticTrading","artifacts","deliveries"));java.util.Iterator<String> it=o.keys();while(it.hasNext())require(keys.contains(it.next()),"批次未知顶层字段");require(Boolean.FALSE.equals(o.opt("automaticTrading")),"批次automaticTrading必须false");JSONObject source=object(o,"source"),asOf=object(o,"asOf");for(String k:new String[]{"system","taskId","generatedAt"})require(!source.optString(k).trim().isEmpty(),"批次来源字段缺失");require(!source.optString("runId",source.optString("scheduledFor")).trim().isEmpty(),"批次runId缺失");double revision=o.optDouble("revision",0);require(revision>=1&&Math.floor(revision)==revision,"批次revision无效");require(asOf.optString("marketDate").matches("[0-9]{4}-[0-9]{2}-[0-9]{2}")&&asOf.optString("timezone").equals("Asia/Shanghai"),"批次日期/时区无效");java.time.LocalDate.parse(asOf.getString("marketDate"));java.time.OffsetDateTime.parse(asOf.getString("observedAt"));JSONArray rows=array(o,"artifacts"),out=new JSONArray();require(rows.length()>0&&rows.length()<=3,"批次需1至3产物");java.util.Set<String> kinds=new java.util.HashSet<>();boolean picks=false,thsEligible=false;for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);String kind=r.optString("kind");require(kinds.add(kind),"批次同类产物重复");if(kind.equals("research-picks")){require(r.optString("schema").equals("webstock.research-picks/v1"),"候选schema无效");JSONArray ps=array(object(r,"payload"),"picks");require(ps.length()>0&&ps.length()<=20,"批次候选需1至20行");java.util.Set<String> codes=new java.util.HashSet<>();java.util.Set<Integer> ranks=new java.util.HashSet<>();for(int j=0;j<ps.length();j++){JSONObject p=ps.getJSONObject(j);String code=p.optString("code");require(code.matches("(000|001|002|003|300|301|302|600|601|603|605|688|689|920)[0-9]{3}")&&codes.add(code),"批次代码无效或重复");double rank=p.has("rank")?p.optDouble("rank",-1):j+1;require(rank>=1&&rank<=20&&Math.floor(rank)==rank&&ranks.add((int)rank),"批次rank无效或重复");require(!p.optString("name").trim().isEmpty()&&!p.optString("thesis").trim().isEmpty(),"批次候选名称/逻辑缺失");list(p,"risks",true);list(p,"evidenceRefs",true);thsEligible=thsEligible||Boolean.TRUE.equals(p.opt("includeInTonghuashun"));}picks=true;}else{require(kind.equals("market-hotspots")||kind.equals("industry-chain-updates"),"批次产物类型无效");require(r.optString("schema").equals("webstock."+kind+"/v1"),"产物kind/schema冲突");JSONObject captured=new JSONObject(json(r)).put("batchOriginal",o);out.put(artifact(captured));}}require(picks&&out.length()>0,"需含候选和热点/产业材料；不导入独立荐股");java.util.Set<String> targets=new java.util.HashSet<>();JSONArray deliveries=array(o,"deliveries");for(int i=0;i<deliveries.length();i++){String target=deliveries.getJSONObject(i).optString("target");require((target.equals("webstock-research")||target.equals("tonghuashun-watchlist"))&&targets.add(target),"批次投递目标无效或重复");}require(targets.contains("webstock-research")&&(!targets.contains("tonghuashun-watchlist")||thsEligible),"批次投递声明无效");return out;}
 static JSONArray decode(String text)throws Exception{require(text.getBytes(StandardCharsets.UTF_8).length<=25*1024*1024,"导入超过25MiB");new EvidenceReviewModel.Syntax(text).check();JSONObject o=new JSONObject(text);JSONArray a=new JSONArray();if(o.optString("schema").equals("sector-research-v1")){JSONArray records=o.getJSONArray("records");for(int i=0;i<records.length();i++)a.put(validate(records.getJSONObject(i)));return a;}if(o.has("hotspots")||o.has("industryChains")){for(String k:new String[]{"hotspots","industryChains"})if(o.has(k)&&!o.isNull(k))a.put(artifact(o.getJSONObject(k)));require(a.length()>0,"没有外部材料");return a;}if(o.optString("schema").equals("webstock.external-research-batch/v1"))return batch(o);return a.put(artifact(o));}
 static JSONObject validate(JSONObject input)throws Exception{if("relation-reviews".equals(input.opt("kind")))return SectorRelationReview.validateVersion(input);if("ai-reports".equals(input.opt("kind")))return SectorAiModel.validateRecord(input);require(json(input).getBytes(StandardCharsets.UTF_8).length<=25*1024*1024,"记录超过25MiB");JSONObject r=new JSONObject(json(input));r.remove("id");String kind=r.optString("kind");JSONObject expected;if(kind.equals("packets"))expected=packet(object(r,"scope"),array(r,"documents"),r.optString("manual"),r.optString("question"));else if(kind.equals("results"))expected=result(object(r,"packetSnapshot"),r.optString("raw"));else if(kind.equals("artifacts"))expected=artifact(object(r,"original"));else if(kind.equals("reviews")){JSONObject c=object(r,"candidate");expected=review(object(r,"sourceSnapshot"),r.optInt("row",-1),c.optString("instrumentId"),c.optString("name"),array(r,"catalogueSnapshot"));}else if(kind.equals("associations")){scope(object(r,"scope"));require(r.optBoolean("acknowledged"),"关联需人工确认");validate(object(r,"artifactSnapshot"));expected=seal(r);}else throw new IllegalArgumentException("记录类型不支持；不导入草稿预览");require(canonicalEqual(input,expected),"记录原文/摘要/身份不一致");return input;}
  static JSONObject review(JSONObject source,int row,String id,String name,JSONArray catalogue)throws Exception{validate(source);JSONArray rows=array(source,source.optString("kind").equals("artifacts")?"rows":"candidates");require(row>=0&&row<rows.length(),"候选行不存在");JSONObject raw=rows.getJSONObject(row),input=new JSONObject(json(raw));if(source.optString("kind").equals("artifacts")){String code=id.substring(id.lastIndexOf(':')+1);boolean found=false;JSONArray codes=array(raw,"relatedCodes");for(int i=0;i<codes.length();i++)if(codes.getString(i).equals(code))found=true;require(found,"代码不在所选原材料行");input=new JSONObject().put("code",code).put("name",name).put("nameOrigin","manual-supplied").put("original",raw);}else{require(raw.optString("name").equals(name),"名称与候选原文不符");input.put("original",raw);}JSONObject audited=EvidenceReviewModel.audit(input,id,catalogue);require(audited.optString("identityState").equals("exact"),"完整身份及名称未与本机目录精确一致");return seal(new JSONObject().put("kind","reviews").put("sourceSnapshot",source).put("row",row).put("candidate",audited).put("catalogueSnapshot",catalogue).put("verification","manual-unverified").put("acknowledged",true));}
 static boolean canonicalEqual(Object a,Object b)throws Exception{return EvidenceReviewModel.canonical(a).equals(EvidenceReviewModel.canonical(b));}
}



